-- N5 grammar curriculum and learner-specific practice history.
begin;
alter table public.grammar_points
 add column if not exists category text not null default 'General',
 add column if not exists difficulty text not null default 'Core',
 add column if not exists sort_order integer not null default 0,
 add column if not exists meaning text not null default '',
 add column if not exists practice_questions jsonb not null default '[]'::jsonb;
create index if not exists grammar_points_level_sort_idx on public.grammar_points(jlpt_level,sort_order) where publication_status='published';
create table if not exists public.user_grammar_practice_attempts(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 grammar_id uuid not null references public.grammar_points(id) on delete cascade,
 question_id text not null, selected_answer text not null, is_correct boolean not null,
 attempted_at timestamptz not null default now()
);
create index if not exists user_grammar_practice_attempts_user_time_idx on public.user_grammar_practice_attempts(user_id,attempted_at desc);
create index if not exists user_grammar_practice_attempts_user_item_idx on public.user_grammar_practice_attempts(user_id,grammar_id,attempted_at desc);
alter table public.user_grammar_practice_attempts enable row level security;
revoke all privileges on public.user_grammar_practice_attempts from public,anon,authenticated;
grant select,insert on public.user_grammar_practice_attempts to authenticated;
grant all privileges on public.user_grammar_practice_attempts to service_role;
drop policy if exists user_grammar_practice_attempts_read_own on public.user_grammar_practice_attempts;
create policy user_grammar_practice_attempts_read_own on public.user_grammar_practice_attempts for select to authenticated using((select auth.uid())=user_id);
drop policy if exists user_grammar_practice_attempts_insert_own on public.user_grammar_practice_attempts;
create policy user_grammar_practice_attempts_insert_own on public.user_grammar_practice_attempts for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.grammar_points g where g.id=user_grammar_practice_attempts.grammar_id and g.publication_status='published'));
do $seed_n5$
declare v_data jsonb := $n5_json$[{"jlpt_level":"N5","sort_order":1,"category":"Foundations","title":"Polite identity","pattern":"Noun は Noun です","meaning":"A is B","explanation":"Noun は Noun です expresses a is b. Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + は + Noun + です","difficulty":"Beginner","examples":[{"japanese":"私は学生です。","romaji":"Watashi wa gakusei desu.","meaning":"I am a student."}],"common_mistakes":["Use the exact construction Noun + は + Noun + です; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-1-meaning","prompt":"What does “Noun は Noun です” mean?","options":["A is not B","A is not B (formal)","Was / were","A is B"],"answer":"A is B","explanation":"Noun は Noun です expresses a is b. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-1-formation","prompt":"Choose the correct formation for “Polite identity”.","options":["Noun + は + Noun + ではありません","Noun + は + Noun + でした","Noun + は + Noun + です","Noun + は + Noun + じゃありません"],"answer":"Noun + は + Noun + です","explanation":"Noun は Noun です expresses a is b. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-1-example","prompt":"Which sentence illustrates “Polite identity”?","options":["昨日は休みでした。","私は学生です。","私は医者じゃありません。","これは問題ではありません。"],"answer":"私は学生です。","explanation":"私は学生です。 (Watashi wa gakusei desu.) means “I am a student.”."},{"id":"n5-1-translation","prompt":"Choose the meaning of: 私は学生です。","options":["I am a student.","I am not a doctor.","This is not a problem.","Yesterday was a day off."],"answer":"I am a student.","explanation":"私は学生です。 (Watashi wa gakusei desu.) means “I am a student.”."}]},{"jlpt_level":"N5","sort_order":2,"category":"Foundations","title":"Polite negative identity","pattern":"Noun は Noun じゃありません","meaning":"A is not B","explanation":"Noun は Noun じゃありません expresses a is not b. Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + は + Noun + じゃありません","difficulty":"Beginner","examples":[{"japanese":"私は医者じゃありません。","romaji":"Watashi wa isha ja arimasen.","meaning":"I am not a doctor."}],"common_mistakes":["Use the exact construction Noun + は + Noun + じゃありません; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-2-meaning","prompt":"What does “Noun は Noun じゃありません” mean?","options":["A is not B (formal)","Was / were","A is not B","A is B"],"answer":"A is not B","explanation":"Noun は Noun じゃありません expresses a is not b. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-2-formation","prompt":"Choose the correct formation for “Polite negative identity”.","options":["Noun + は + Noun + でした","Noun + は + Noun + じゃありません","Noun + は + Noun + です","Noun + は + Noun + ではありません"],"answer":"Noun + は + Noun + じゃありません","explanation":"Noun は Noun じゃありません expresses a is not b. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-2-example","prompt":"Which sentence illustrates “Polite negative identity”?","options":["私は医者じゃありません。","私は学生です。","これは問題ではありません。","昨日は休みでした。"],"answer":"私は医者じゃありません。","explanation":"私は医者じゃありません。 (Watashi wa isha ja arimasen.) means “I am not a doctor.”."},{"id":"n5-2-translation","prompt":"Choose the meaning of: 私は医者じゃありません。","options":["I am a student.","This is not a problem.","Yesterday was a day off.","I am not a doctor."],"answer":"I am not a doctor.","explanation":"私は医者じゃありません。 (Watashi wa isha ja arimasen.) means “I am not a doctor.”."}]},{"jlpt_level":"N5","sort_order":3,"category":"Foundations","title":"Formal negative identity","pattern":"Noun は Noun ではありません","meaning":"A is not B (formal)","explanation":"Noun は Noun ではありません expresses a is not b (formal). Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + は + Noun + ではありません","difficulty":"Beginner","examples":[{"japanese":"これは問題ではありません。","romaji":"Kore wa mondai dewa arimasen.","meaning":"This is not a problem."}],"common_mistakes":["Use the exact construction Noun + は + Noun + ではありません; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-3-meaning","prompt":"What does “Noun は Noun ではありません” mean?","options":["Was / were","A is not B (formal)","A is B","A is not B"],"answer":"A is not B (formal)","explanation":"Noun は Noun ではありません expresses a is not b (formal). Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-3-formation","prompt":"Choose the correct formation for “Formal negative identity”.","options":["Noun + は + Noun + ではありません","Noun + は + Noun + です","Noun + は + Noun + じゃありません","Noun + は + Noun + でした"],"answer":"Noun + は + Noun + ではありません","explanation":"Noun は Noun ではありません expresses a is not b (formal). Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-3-example","prompt":"Which sentence illustrates “Formal negative identity”?","options":["私は学生です。","私は医者じゃありません。","昨日は休みでした。","これは問題ではありません。"],"answer":"これは問題ではありません。","explanation":"これは問題ではありません。 (Kore wa mondai dewa arimasen.) means “This is not a problem.”."},{"id":"n5-3-translation","prompt":"Choose the meaning of: これは問題ではありません。","options":["I am not a doctor.","Yesterday was a day off.","This is not a problem.","I am a student."],"answer":"This is not a problem.","explanation":"これは問題ではありません。 (Kore wa mondai dewa arimasen.) means “This is not a problem.”."}]},{"jlpt_level":"N5","sort_order":4,"category":"Foundations","title":"Polite past identity","pattern":"Noun は Noun でした","meaning":"Was / were","explanation":"Noun は Noun でした expresses was / were. Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + は + Noun + でした","difficulty":"Beginner","examples":[{"japanese":"昨日は休みでした。","romaji":"Kinou wa yasumi deshita.","meaning":"Yesterday was a day off."}],"common_mistakes":["Use the exact construction Noun + は + Noun + でした; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-4-meaning","prompt":"What does “Noun は Noun でした” mean?","options":["Was / were","A is B","A is not B","A is not B (formal)"],"answer":"Was / were","explanation":"Noun は Noun でした expresses was / were. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-4-formation","prompt":"Choose the correct formation for “Polite past identity”.","options":["Noun + は + Noun + です","Noun + は + Noun + じゃありません","Noun + は + Noun + ではありません","Noun + は + Noun + でした"],"answer":"Noun + は + Noun + でした","explanation":"Noun は Noun でした expresses was / were. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-4-example","prompt":"Which sentence illustrates “Polite past identity”?","options":["私は医者じゃありません。","これは問題ではありません。","昨日は休みでした。","私は学生です。"],"answer":"昨日は休みでした。","explanation":"昨日は休みでした。 (Kinou wa yasumi deshita.) means “Yesterday was a day off.”."},{"id":"n5-4-translation","prompt":"Choose the meaning of: 昨日は休みでした。","options":["This is not a problem.","Yesterday was a day off.","I am a student.","I am not a doctor."],"answer":"Yesterday was a day off.","explanation":"昨日は休みでした。 (Kinou wa yasumi deshita.) means “Yesterday was a day off.”."}]},{"jlpt_level":"N5","sort_order":5,"category":"Foundations","title":"Past negative identity","pattern":"Noun は Noun じゃありませんでした","meaning":"Was not / were not","explanation":"Noun は Noun じゃありませんでした expresses was not / were not. Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + は + Noun + じゃありませんでした","difficulty":"Beginner","examples":[{"japanese":"昨日は休みじゃありませんでした。","romaji":"Kinou wa yasumi ja arimasen deshita.","meaning":"Yesterday was not a day off."}],"common_mistakes":["Use the exact construction Noun + は + Noun + じゃありませんでした; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-5-meaning","prompt":"What does “Noun は Noun じゃありませんでした” mean?","options":["A is B","A is not B","A is not B (formal)","Was not / were not"],"answer":"Was not / were not","explanation":"Noun は Noun じゃありませんでした expresses was not / were not. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-5-formation","prompt":"Choose the correct formation for “Past negative identity”.","options":["Noun + は + Noun + じゃありません","Noun + は + Noun + ではありません","Noun + は + Noun + じゃありませんでした","Noun + は + Noun + です"],"answer":"Noun + は + Noun + じゃありませんでした","explanation":"Noun は Noun じゃありませんでした expresses was not / were not. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-5-example","prompt":"Which sentence illustrates “Past negative identity”?","options":["これは問題ではありません。","昨日は休みじゃありませんでした。","私は学生です。","私は医者じゃありません。"],"answer":"昨日は休みじゃありませんでした。","explanation":"昨日は休みじゃありませんでした。 (Kinou wa yasumi ja arimasen deshita.) means “Yesterday was not a day off.”."},{"id":"n5-5-translation","prompt":"Choose the meaning of: 昨日は休みじゃありませんでした。","options":["Yesterday was not a day off.","I am a student.","I am not a doctor.","This is not a problem."],"answer":"Yesterday was not a day off.","explanation":"昨日は休みじゃありませんでした。 (Kinou wa yasumi ja arimasen deshita.) means “Yesterday was not a day off.”."}]},{"jlpt_level":"N5","sort_order":6,"category":"Foundations","title":"Plain copula","pattern":"Noun だ","meaning":"A is B (casual)","explanation":"Noun だ expresses a is b (casual). Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun / な-adjective + だ","difficulty":"Beginner","examples":[{"japanese":"これは本だ。","romaji":"Kore wa hon da.","meaning":"This is a book."}],"common_mistakes":["Use the exact construction Noun / な-adjective + だ; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-6-meaning","prompt":"What does “Noun だ” mean?","options":["A is not B","A is not B (formal)","A is B (casual)","A is B"],"answer":"A is B (casual)","explanation":"Noun だ expresses a is b (casual). Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-6-formation","prompt":"Choose the correct formation for “Plain copula”.","options":["Noun + は + Noun + ではありません","Noun / な-adjective + だ","Noun + は + Noun + です","Noun + は + Noun + じゃありません"],"answer":"Noun / な-adjective + だ","explanation":"Noun だ expresses a is b (casual). Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-6-example","prompt":"Which sentence illustrates “Plain copula”?","options":["これは本だ。","私は学生です。","私は医者じゃありません。","これは問題ではありません。"],"answer":"これは本だ。","explanation":"これは本だ。 (Kore wa hon da.) means “This is a book.”."},{"id":"n5-6-translation","prompt":"Choose the meaning of: これは本だ。","options":["I am a student.","I am not a doctor.","This is not a problem.","This is a book."],"answer":"This is a book.","explanation":"これは本だ。 (Kore wa hon da.) means “This is a book.”."}]},{"jlpt_level":"N5","sort_order":7,"category":"Foundations","title":"Yes-no question","pattern":"Sentence + か","meaning":"Turn a statement into a question","explanation":"Sentence + か expresses turn a statement into a question. Identify the role of each phrase, then apply the formation rule in context.","formation":"Polite sentence + か","difficulty":"Beginner","examples":[{"japanese":"田中さんは学生ですか。","romaji":"Tanaka-san wa gakusei desu ka.","meaning":"Is Tanaka a student?"}],"common_mistakes":["Use the exact construction Polite sentence + か; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-7-meaning","prompt":"What does “Sentence + か” mean?","options":["A is not B (formal)","Turn a statement into a question","A is B","A is not B"],"answer":"Turn a statement into a question","explanation":"Sentence + か expresses turn a statement into a question. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-7-formation","prompt":"Choose the correct formation for “Yes-no question”.","options":["Polite sentence + か","Noun + は + Noun + です","Noun + は + Noun + じゃありません","Noun + は + Noun + ではありません"],"answer":"Polite sentence + か","explanation":"Sentence + か expresses turn a statement into a question. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-7-example","prompt":"Which sentence illustrates “Yes-no question”?","options":["私は学生です。","私は医者じゃありません。","これは問題ではありません。","田中さんは学生ですか。"],"answer":"田中さんは学生ですか。","explanation":"田中さんは学生ですか。 (Tanaka-san wa gakusei desu ka.) means “Is Tanaka a student?”."},{"id":"n5-7-translation","prompt":"Choose the meaning of: 田中さんは学生ですか。","options":["I am not a doctor.","This is not a problem.","Is Tanaka a student?","I am a student."],"answer":"Is Tanaka a student?","explanation":"田中さんは学生ですか。 (Tanaka-san wa gakusei desu ka.) means “Is Tanaka a student?”."}]},{"jlpt_level":"N5","sort_order":8,"category":"Particles","title":"Topic は","pattern":"Noun + は","meaning":"Topic of the sentence","explanation":"Noun + は expresses topic of the sentence. Identify the role of each phrase, then apply the formation rule in context.","formation":"Topic + は + comment","difficulty":"Beginner","examples":[{"japanese":"今日は暑いです。","romaji":"Kyou wa atsui desu.","meaning":"It is hot today."}],"common_mistakes":["Use the exact construction Topic + は + comment; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-8-meaning","prompt":"What does “Noun + は” mean?","options":["Topic of the sentence","Subject / newly identified information","Direct object","Also / too"],"answer":"Topic of the sentence","explanation":"Noun + は expresses topic of the sentence. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-8-formation","prompt":"Choose the correct formation for “Topic は”.","options":["Subject + が + predicate","Object + を + verb","Noun + も + predicate","Topic + は + comment"],"answer":"Topic + は + comment","explanation":"Noun + は expresses topic of the sentence. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-8-example","prompt":"Which sentence illustrates “Topic は”?","options":["水を飲みます。","私も学生です。","今日は暑いです。","猫がいます。"],"answer":"今日は暑いです。","explanation":"今日は暑いです。 (Kyou wa atsui desu.) means “It is hot today.”."},{"id":"n5-8-translation","prompt":"Choose the meaning of: 今日は暑いです。","options":["I am a student too.","It is hot today.","There is a cat.","I drink water."],"answer":"It is hot today.","explanation":"今日は暑いです。 (Kyou wa atsui desu.) means “It is hot today.”."}]},{"jlpt_level":"N5","sort_order":9,"category":"Particles","title":"Subject が","pattern":"Noun + が","meaning":"Subject / newly identified information","explanation":"Noun + が expresses subject / newly identified information. Identify the role of each phrase, then apply the formation rule in context.","formation":"Subject + が + predicate","difficulty":"Beginner","examples":[{"japanese":"猫がいます。","romaji":"Neko ga imasu.","meaning":"There is a cat."}],"common_mistakes":["Use the exact construction Subject + が + predicate; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-9-meaning","prompt":"What does “Noun + が” mean?","options":["Topic of the sentence","Direct object","Also / too","Subject / newly identified information"],"answer":"Subject / newly identified information","explanation":"Noun + が expresses subject / newly identified information. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-9-formation","prompt":"Choose the correct formation for “Subject が”.","options":["Object + を + verb","Noun + も + predicate","Subject + が + predicate","Topic + は + comment"],"answer":"Subject + が + predicate","explanation":"Noun + が expresses subject / newly identified information. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-9-example","prompt":"Which sentence illustrates “Subject が”?","options":["私も学生です。","猫がいます。","今日は暑いです。","水を飲みます。"],"answer":"猫がいます。","explanation":"猫がいます。 (Neko ga imasu.) means “There is a cat.”."},{"id":"n5-9-translation","prompt":"Choose the meaning of: 猫がいます。","options":["There is a cat.","It is hot today.","I drink water.","I am a student too."],"answer":"There is a cat.","explanation":"猫がいます。 (Neko ga imasu.) means “There is a cat.”."}]},{"jlpt_level":"N5","sort_order":10,"category":"Particles","title":"Direct object を","pattern":"Noun + を + transitive verb","meaning":"Direct object","explanation":"Noun + を + transitive verb expresses direct object. Identify the role of each phrase, then apply the formation rule in context.","formation":"Object + を + verb","difficulty":"Beginner","examples":[{"japanese":"水を飲みます。","romaji":"Mizu o nomimasu.","meaning":"I drink water."}],"common_mistakes":["Use the exact construction Object + を + verb; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-10-meaning","prompt":"What does “Noun + を + transitive verb” mean?","options":["Subject / newly identified information","Also / too","Direct object","Topic of the sentence"],"answer":"Direct object","explanation":"Noun + を + transitive verb expresses direct object. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-10-formation","prompt":"Choose the correct formation for “Direct object を”.","options":["Noun + も + predicate","Object + を + verb","Topic + は + comment","Subject + が + predicate"],"answer":"Object + を + verb","explanation":"Noun + を + transitive verb expresses direct object. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-10-example","prompt":"Which sentence illustrates “Direct object を”?","options":["水を飲みます。","今日は暑いです。","猫がいます。","私も学生です。"],"answer":"水を飲みます。","explanation":"水を飲みます。 (Mizu o nomimasu.) means “I drink water.”."},{"id":"n5-10-translation","prompt":"Choose the meaning of: 水を飲みます。","options":["It is hot today.","There is a cat.","I am a student too.","I drink water."],"answer":"I drink water.","explanation":"水を飲みます。 (Mizu o nomimasu.) means “I drink water.”."}]},{"jlpt_level":"N5","sort_order":11,"category":"Particles","title":"Also も","pattern":"Noun + も","meaning":"Also / too","explanation":"Noun + も expresses also / too. Identify the role of each phrase, then apply the formation rule in context.","formation":"Noun + も + predicate","difficulty":"Beginner","examples":[{"japanese":"私も学生です。","romaji":"Watashi mo gakusei desu.","meaning":"I am a student too."}],"common_mistakes":["Use the exact construction Noun + も + predicate; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-11-meaning","prompt":"What does “Noun + も” mean?","options":["Direct object","Also / too","Topic of the sentence","Subject / newly identified information"],"answer":"Also / too","explanation":"Noun + も expresses also / too. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-11-formation","prompt":"Choose the correct formation for “Also も”.","options":["Noun + も + predicate","Topic + は + comment","Subject + が + predicate","Object + を + verb"],"answer":"Noun + も + predicate","explanation":"Noun + も expresses also / too. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-11-example","prompt":"Which sentence illustrates “Also も”?","options":["今日は暑いです。","猫がいます。","水を飲みます。","私も学生です。"],"answer":"私も学生です。","explanation":"私も学生です。 (Watashi mo gakusei desu.) means “I am a student too.”."},{"id":"n5-11-translation","prompt":"Choose the meaning of: 私も学生です。","options":["There is a cat.","I drink water.","I am a student too.","It is hot today."],"answer":"I am a student too.","explanation":"私も学生です。 (Watashi mo gakusei desu.) means “I am a student too.”."}]},{"jlpt_level":"N5","sort_order":12,"category":"Particles","title":"Possessive の","pattern":"Noun 1 + の + Noun 2","meaning":"Possession / relationship","explanation":"Noun 1 + の + Noun 2 expresses possession / relationship. Identify the role of each phrase, then apply the formation rule in context.","formation":"Owner + の + owned noun","difficulty":"Beginner","examples":[{"japanese":"これは私の本です。","romaji":"Kore wa watashi no hon desu.","meaning":"This is my book."}],"common_mistakes":["Use the exact construction Owner + の + owned noun; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-12-meaning","prompt":"What does “Noun 1 + の + Noun 2” mean?","options":["Possession / relationship","Topic of the sentence","Subject / newly identified information","Direct object"],"answer":"Possession / relationship","explanation":"Noun 1 + の + Noun 2 expresses possession / relationship. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-12-formation","prompt":"Choose the correct formation for “Possessive の”.","options":["Topic + は + comment","Subject + が + predicate","Object + を + verb","Owner + の + owned noun"],"answer":"Owner + の + owned noun","explanation":"Noun 1 + の + Noun 2 expresses possession / relationship. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-12-example","prompt":"Which sentence illustrates “Possessive の”?","options":["猫がいます。","水を飲みます。","これは私の本です。","今日は暑いです。"],"answer":"これは私の本です。","explanation":"これは私の本です。 (Kore wa watashi no hon desu.) means “This is my book.”."},{"id":"n5-12-translation","prompt":"Choose the meaning of: これは私の本です。","options":["I drink water.","This is my book.","It is hot today.","There is a cat."],"answer":"This is my book.","explanation":"これは私の本です。 (Kore wa watashi no hon desu.) means “This is my book.”."}]},{"jlpt_level":"N5","sort_order":13,"category":"Particles","title":"Specific time に","pattern":"Time + に","meaning":"At a specific time","explanation":"Time + に expresses at a specific time. Identify the role of each phrase, then apply the formation rule in context.","formation":"Specific time + に + action","difficulty":"Beginner","examples":[{"japanese":"七時に起きます。","romaji":"Shichi-ji ni okimasu.","meaning":"I get up at seven."}],"common_mistakes":["Use the exact construction Specific time + に + action; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-13-meaning","prompt":"What does “Time + に” mean?","options":["Topic of the sentence","Subject / newly identified information","Direct object","At a specific time"],"answer":"At a specific time","explanation":"Time + に expresses at a specific time. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-13-formation","prompt":"Choose the correct formation for “Specific time に”.","options":["Subject + が + predicate","Object + を + verb","Specific time + に + action","Topic + は + comment"],"answer":"Specific time + に + action","explanation":"Time + に expresses at a specific time. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-13-example","prompt":"Which sentence illustrates “Specific time に”?","options":["水を飲みます。","七時に起きます。","今日は暑いです。","猫がいます。"],"answer":"七時に起きます。","explanation":"七時に起きます。 (Shichi-ji ni okimasu.) means “I get up at seven.”."},{"id":"n5-13-translation","prompt":"Choose the meaning of: 七時に起きます。","options":["I get up at seven.","It is hot today.","There is a cat.","I drink water."],"answer":"I get up at seven.","explanation":"七時に起きます。 (Shichi-ji ni okimasu.) means “I get up at seven.”."}]},{"jlpt_level":"N5","sort_order":14,"category":"Particles","title":"Destination に","pattern":"Place + に + movement verb","meaning":"To a destination","explanation":"Place + に + movement verb expresses to a destination. Identify the role of each phrase, then apply the formation rule in context.","formation":"Place + に + 行く / 来る / 帰る","difficulty":"Beginner","examples":[{"japanese":"学校に行きます。","romaji":"Gakkou ni ikimasu.","meaning":"I go to school."}],"common_mistakes":["Use the exact construction Place + に + 行く / 来る / 帰る; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-14-meaning","prompt":"What does “Place + に + movement verb” mean?","options":["Subject / newly identified information","Direct object","To a destination","Topic of the sentence"],"answer":"To a destination","explanation":"Place + に + movement verb expresses to a destination. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-14-formation","prompt":"Choose the correct formation for “Destination に”.","options":["Object + を + verb","Place + に + 行く / 来る / 帰る","Topic + は + comment","Subject + が + predicate"],"answer":"Place + に + 行く / 来る / 帰る","explanation":"Place + に + movement verb expresses to a destination. Identify the role of each phrase, then apply the formation rule in context."},{"id":"n5-14-example","prompt":"Which sentence illustrates “Destination に”?","options":["学校に行きます。","今日は暑いです。","猫がいます。","水を飲みます。"],"answer":"学校に行きます。","explanation":"学校に行きます。 (Gakkou ni ikimasu.) means “I go to school.”."},{"id":"n5-14-translation","prompt":"Choose the meaning of: 学校に行きます。","options":["It is hot today.","There is a cat.","I drink water.","I go to school."],"answer":"I go to school.","explanation":"学校に行きます。 (Gakkou ni ikimasu.) means “I go to school.”."}]},{"jlpt_level":"N5","sort_order":15,"category":"Particles","title":"Existence location に","pattern":"Place + に + あります / います","meaning":"At / in a place (existence)","explanation":"Place + に + あります / います expresses at / in a place (existence). Identify the role of each phrase, then apply the formation rule in context.","formation":"Place + に + thing + が + あります / います","difficulty":"Beginner","examples":[{"japanese":"部屋に猫がいます。","romaji":"Heya ni neko ga imasu.","meaning":"There is a cat in the room."}],"common_mistakes":["Use the exact construction Place + に + thing + が + あります / います; do not replace it with a similar-looking pattern."],"practice_questions":[{"id":"n5-15-mea