begin
 insert into public.grammar_points(jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,category,difficulty,sort_order,meaning,practice_questions,publication_status)
 select 'N5'::public.jlpt_level,r.title,r.pattern,r.explanation,r.formation,r.examples,r.common_mistakes,r.category,r.difficulty,r.sort_order,r.meaning,r.practice_questions,'published'::public.publication_status
 from jsonb_to_recordset(v_data) as r(sort_order integer,category text,title text,pattern text,meaning text,explanation text,formation text,difficulty text,examples jsonb,common_mistakes jsonb,practice_questions jsonb,jlpt_level text)
 on conflict(jlpt_level,pattern) do update set title=excluded.title,meaning=excluded.meaning,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,category=excluded.category,difficulty=excluded.difficulty,sort_order=excluded.sort_order,practice_questions=excluded.practice_questions,publication_status='published',updated_at=now();
end;
$seed_n5$;
